{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM 是明确参与组织任务的角色；节点本身未推断额外权限。",
      "sources": [{"quote": "由 PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "service",
      "verdict": "SUPPORT",
      "reason": "服务是探测对象，也是重启禁令的对象；来源未引入另一个服务。",
      "sources": [
        {"quote": "服务探测", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "不得重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "report",
      "verdict": "SUPPORT",
      "reason": "形成文件支持将该文件解释为生成输出，而非既有输入。",
      "sources": [{"quote": "形成 service-probe.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "任务直接指定组织服务探测，支持 REQUIRED 的组织事件。",
      "sources": [{"quote": "本次任务由 PM 组织服务探测", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "probe",
      "verdict": "SUPPORT",
      "reason": "服务探测是组织事件的补语；来源没有明确指定探测执行者，节点也未将其提升为独立要求。",
      "sources": [{"quote": "组织服务探测", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "generate",
      "verdict": "SUPPORT",
      "reason": "形成文件与组织事件并列，是任务明确要求的产出行为。",
      "sources": [{"quote": "本次任务由 PM 组织服务探测并形成 service-probe.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "retry",
      "verdict": "SUPPORT",
      "reason": "最多重试支持有上限的重试许可，不要求实际重试，也不要求执行五次。",
      "sources": [{"quote": "最多重试 5 次", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "successful_returns",
      "verdict": "SUPPORT",
      "reason": "至少两次成功返回是完成的条件前件，并未被声明为独立执行事件。",
      "sources": [{"quote": "至少 2 次返回成功状态后才可完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "complete",
      "verdict": "SUPPORT",
      "reason": "才可完成支持受必要条件限制的完成许可；不表示必须完成，也不表示成功次数达标是充分条件。",
      "sources": [
        {"quote": "本次任务", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "至少 2 次返回成功状态后才可完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "restart",
      "verdict": "SUPPORT",
      "reason": "不得明确禁止重启服务。FORBIDDEN 修饰肯定形式的重启事件，不应再解释为否定事件。",
      "sources": [{"quote": "不得重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "agent_organize",
      "verdict": "SUPPORT",
      "reason": "由 PM 组织明确绑定 PM 为组织行为的执行者，依据是参与谓词而非角色名称。",
      "sources": [{"quote": "由 PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "probe_complement",
      "verdict": "SUPPORT",
      "reason": "组织服务探测支持探测作为组织行为的结构性补语。",
      "sources": [{"quote": "组织服务探测", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "probe_material",
      "verdict": "SUPPORT",
      "reason": "服务探测支持服务作为被探测对象；该绑定不意味着修改服务。",
      "sources": [{"quote": "服务探测", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "agent_generate",
      "verdict": "SUPPORT",
      "reason": "由 PM 引出的主体通过并列谓词延续到形成文件，支持 PM 参与形成行为。",
      "sources": [{"quote": "由 PM 组织服务探测并形成 service-probe.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "organized_and_generated",
      "verdict": "SUPPORT",
      "reason": "并明确连接组织与形成两个谓词；关系没有额外强加执行顺序。",
      "sources": [{"quote": "组织服务探测并形成 service-probe.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "generated_report",
      "verdict": "SUPPORT",
      "reason": "文件是形成事件的结果，不是该事件的依据、格式或输入。",
      "sources": [{"quote": "形成 service-probe.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "retry_probe",
      "verdict": "SUPPORT",
      "reason": "在服务探测语境中，重试自然承接探测操作；这是上下文支持的绑定，未指定重试执行者。",
      "sources": [{"quote": "服务探测并形成 service-probe.md，最多重试 5 次", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "retry_limit",
      "verdict": "SUPPORT",
      "reason": "最多五次明确将数量上限绑定到重试事件。",
      "sources": [{"quote": "最多重试 5 次", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "completion_guard",
      "verdict": "SUPPORT",
      "reason": "后才可将成功次数条件绑定到完成许可，表达必要门槛而非普通时间先后。",
      "sources": [{"quote": "至少 2 次返回成功状态后才可完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "task_completion_threshold",
      "verdict": "SUPPORT",
      "reason": "本次任务提供完成对象，后才可完成提供其完成门槛；两端均有来源见证。",
      "sources": [
        {"quote": "本次任务", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "至少 2 次返回成功状态后才可完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "restart_material",
      "verdict": "SUPPORT",
      "reason": "服务是被禁止的重启事件的直接对象。",
      "sources": [{"quote": "重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "restart_prohibition",
      "verdict": "SUPPORT",
      "reason": "任务语境中的不得重启服务支持任务范围内的重启禁令，不推断任何执行者。",
      "sources": [
        {"quote": "本次任务", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "不得重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "retry_cap",
      "verdict": "SUPPORT",
      "reason": "最多对应 LTE，五次计量的是重试执行次数，不是总探测次数或文件数量。",
      "sources": [{"quote": "最多重试 5 次", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "success_count",
      "verdict": "SUPPORT",
      "reason": "至少对应 GTE，两次计量的是成功返回次数，并作为完成验收门槛。",
      "sources": [{"quote": "至少 2 次返回成功状态后才可完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "success_guard",
      "verdict": "SUPPORT",
      "reason": "引用成功返回状态作为完成条件有直接依据；状态引用自身不产生执行义务。",
      "sources": [{"quote": "至少 2 次返回成功状态后才可完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    }
  ],
